EXECUTABLE_EXTENSIONS = (".exe",)

#: PATH / PATHEXT 各条目之间的分隔符。
_ENV_SEPARATOR = os.pathsep

#: 出现在命令名里就说明它是「路径」而不是「名字」的字符。
#: Windows 的文件名不允许包含 ``:``，所以盘符也算路径线索。
_PATH_HINTS = tuple(item for item in (os.sep, os.altsep, ":") if item)


class _Extensions(tuple):
    """按优先级排列的可执行扩展名序列。

    语义上就是一个元组，另外提供两点便利：

    * 允许与 ``list`` 直接比较，调用方两种写法都能用；
    * 比较时忽略大小写，与 Windows 文件名不区分大小写的行为一致。
    """

    __slots__ = ()

    def __eq__(self, other):
        if isinstance(other, (list, tuple)):
            return _normalized(other) == _normalized(self)
        return NotImplemented

    def __ne__(self, other):
        result = self.__eq__(other)
        if result is NotImplemented:
            return result
        return not result

    __hash__ = tuple.__hash__


def _normalized(exts):
    """把扩展名序列规整成可比较的小写元组。"""
    return tuple(str(ext).lower() for ext in exts)


def search_dirs():
    """返回 PATH 中需要搜索的目录列表。"""
    raw = os.environ.get("PATH", "")
    return [d for d in raw.split(os.pathsep) if d]


def executable_extensions():
    """返回按优先级排列的可执行扩展名。

    优先使用环境变量 :envvar:`PATHEXT`（保持其中声明的顺序）；
    它缺失或为空时才退回内置兜底值 :data:`EXECUTABLE_EXTENSIONS`。
    """
    raw = os.environ.get("PATHEXT")
    if raw:
        exts = []
        for item in raw.split(_ENV_SEPARATOR):
            item = item.strip()
            if not item:
                continue
            if not item.startswith("."):
                # PATHEXT 里偶尔会出现漏写点号的条目，补齐后再用。
                item = "." + item
            exts.append(item)
        if exts:
            return _Extensions(exts)
    return _Extensions(EXECUTABLE_EXTENSIONS)


def _candidate_names(name):
    """返回 ``name`` 在每个目录下应当依次试探的文件名。"""
    exts = executable_extensions()
    suffix = os.path.splitext(name)[1]
    if suffix and suffix.lower() in _normalized(exts):
        # 名字本身已经带可执行扩展名：原样查找，不再叠加一层。
        return [name]

    candidates = ["%s%s" % (name, ext) for ext in exts]
    if suffix:
        # 带了扩展名但不在 PATHEXT 里（例如调用方写死的 ``.txt``）：
        # 先按 PATHEXT 叠加试探，最后再看原名本身是否存在。
        candidates.append(name)
    return candidates


def _is_path_like(name):
    """``name`` 里是否已经含有目录信息（绝对/相对路径、盘符）。"""
    if os.path.isabs(name):
        return True
    return any(hint in name for hint in _PATH_HINTS)


def resolve(name):
    """把 ``name`` 解析成磁盘上的绝对路径。

    找不到时抛 :class:`CommandNotFound`。
    """
    if not name:
        raise CommandNotFound(name)

    candidates = _candidate_names(name)

    if _is_path_like(name):
        # 调用方给了路径，就不该再去 PATH 上按名字搜索。
        for candidate in candidates:
            path = os.path.abspath(candidate)
            if os.path.isfile(path):
                return path
        raise CommandNotFound(name)

    for directory in search_dirs():
        for candidate in candidates:
            path = os.path.join(directory, candidate)
            if os.path.isfile(path):
                return os.path.abspath(path)

    raise CommandNotFound(name)

